"""
    Compares two values and returns:
        true when the first value is greater than the second value.
        false when the first value is less than or equivalent to the second value.
    See https://docs.mongodb.com/manual/reference/operator/aggregation/gt/
    for more details
    :param x: first value or expression
    :param y: second value or expression
    :return: Aggregation operator
    """
def GT(x: Any = None, y: Any = None) -> object {
    if ((x is None) and (y is None)) {
        return {'$gt': []};
    }
    return {'$gt': [x, y]};
}

"""
    Divides two floats where the second must be non-zero, otherwise a
    ZeroDivisionError is raise.

    :type x: float
    :param x: numerator
    :type y: float != 0
    :param y: denominator
    :rtype: float
    """
def divide(x: Any, y: Any) -> object {
    if (y != 0) {
        return (x / y);
    } else {
        raise ZeroDivisionError;
    }
}

"""
    Truncates a string to a given length with "..." at the end if needed
    """
def truncate(string: Any, length: Any) -> object {
    return string[:(length - 3)].ljust(length, ".");
}

