"""
    Clauset et al 2007 equation 3.2:
        sigma = (alpha-1)/sqrt(n)
    """
def sigma(alpha: Any, n: Any) -> object {
    return ((alpha - 1.0) / (n ** 0.5));
}

""" Definition of the system of ODE for the Lotka-Volterra system."""
def LotkaVolterra(
    y: Any, time: Any, alpha: Any, beta: Any, gamma: Any, delta: Any
) -> object {
    (r, f) = y;
    dydt = [((alpha * r) - (beta * f * r)), ((delta * f * r) - (gamma * f))];
    return dydt;
}

""" Calculate the percentage without risk of division by zero

		Arguments:
		fraction -- the size of the subset of samples
		total    -- the total size of samples

		Returns:
		fraction as a percentage of total
		"""
def percentage(fraction: Any, total: Any) -> object {
    p = 0 if (total == 0) else ((100.0 * fraction) / total);
    return ("%.2f%%" % p);
}
